import sys

def main():
    s = sys.stdin.read().split()[0]
    last = {}
    for i, c in enumerate(s):
        last[c] = i
    total = 0
    start = 0
    end = 0
    for i, c in enumerate(s):
        if last[c] > end:
            end = last[c]
        if i == end:
            total += (i - start + 1) ** 2
            start = i + 1
            end = i + 1
    print(total)

